begin;
alter table public.profiles add column if not exists email text;
insert into public.profiles(id,full_name,email,role_id,status) select u.id,coalesce(u.raw_user_meta_data->>'full_name',split_part(u.email,'@',1)),u.email,(select id from public.roles where slug=case when not exists(select 1 from public.profiles) then 'admin' else 'cashier' end),true from auth.users u on conflict(id) do update set email=excluded.email;
update public.profiles set role_id=(select id from public.roles where slug='admin') where id=(select id from auth.users order by created_at limit 1) and not exists(select 1 from public.profiles p join public.roles r on r.id=p.role_id where r.slug='admin');
create or replace function public.handle_new_user() returns trigger language plpgsql security definer set search_path=public as $$begin insert into public.profiles(id,full_name,email,role_id) values(new.id,coalesce(new.raw_user_meta_data->>'full_name',new.email),new.email,(select id from public.roles where slug='cashier')) on conflict(id) do nothing;return new;end;$$;
create or replace function public.set_user_status(p_user_id uuid,p_status boolean) returns void language plpgsql security definer set search_path=public as $$begin if not public.has_permission('users.manage') then raise exception 'Forbidden';end if;if p_user_id=auth.uid() and not p_status then raise exception 'You cannot deactivate your own account';end if;update public.profiles set status=p_status where id=p_user_id;insert into public.activity_logs(user_id,action,module,entity_type,entity_id,metadata) values(auth.uid(),'user_status_changed','users','profile',p_user_id::text,jsonb_build_object('status',p_status));end;$$;
create or replace function public.create_role(p_name text,p_slug text,p_description text) returns bigint language plpgsql security definer set search_path=public as $$declare v_id bigint;begin if not public.has_permission('roles.manage') then raise exception 'Forbidden';end if;insert into public.roles(name,slug,description) values(trim(p_name),lower(regexp_replace(trim(p_slug),'[^a-zA-Z0-9]+','_','g')),p_description) returning id into v_id;return v_id;end;$$;
create or replace function public.set_role_permissions(p_role_id bigint,p_permission_ids bigint[]) returns void language plpgsql security definer set search_path=public as $$begin if not public.has_permission('roles.manage') then raise exception 'Forbidden';end if;if exists(select 1 from public.roles where id=p_role_id and slug='admin') then raise exception 'Admin permissions cannot be reduced';end if;delete from public.role_permissions where role_id=p_role_id;insert into public.role_permissions(role_id,permission_id) select p_role_id,unnest(p_permission_ids);insert into public.activity_logs(user_id,action,module,entity_type,entity_id,metadata) values(auth.uid(),'role_permissions_updated','roles','role',p_role_id::text,jsonb_build_object('permission_ids',p_permission_ids));end;$$;
grant execute on function public.set_user_status(uuid,boolean) to authenticated;grant execute on function public.create_role(text,text,text) to authenticated;grant execute on function public.set_role_permissions(bigint,bigint[]) to authenticated;
commit;
